import type { Metadata } from 'next'
import Link from 'next/link'
import { headers } from 'next/headers'
import { ViewAllPostsButton } from '@/components/ViewAllPostsButton'
import { POSTS_API, type Post } from '@/lib/posts'

export const metadata: Metadata = {
  title: 'Home',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

// Replaces `getServerSideProps`: reading `headers()` and fetching with
// `cache: 'no-store'` renders this page on every request.
export default async function HomePage() {
  const headersList = await headers()
  const userAgent = headersList.get('user-agent') || ''

  const posts: Post[] = await fetch(`${POSTS_API}/posts?_limit=5`, {
    cache: 'no-store',
  }).then((res) => res.json())

  const timestamp = new Date().toISOString()

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <ViewAllPostsButton />
    </div>
  )
}

