import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/BackButton'
import { POSTS_API, type Comment, type Post } from '@/lib/posts'

// ISR: replaces `getStaticProps` with `revalidate: 300` (5 minutes).
export const revalidate = 300

// `dynamicParams` defaults to `true`, which replaces `fallback: 'blocking'`:
// ids that were not prerendered are rendered on demand at request time.

type BlogPostPageProps = {
  params: Promise<{ id: string }>
}

// Replaces `getStaticPaths`.
export async function generateStaticParams(): Promise<{ id: string }[]> {
  const posts: Post[] = await fetch(`${POSTS_API}/posts`, {
    next: { revalidate: 300 },
  }).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({ id: String(post.id) }))
}

async function getPost(id: string): Promise<Post | null> {
  const res = await fetch(`${POSTS_API}/posts/${id}`, {
    next: { revalidate: 300 },
  })
  if (!res.ok) return null
  return res.json()
}

async function getComments(id: string): Promise<Comment[]> {
  const res = await fetch(`${POSTS_API}/posts/${id}/comments`, {
    next: { revalidate: 300 },
  })
  if (!res.ok) return []
  return res.json()
}

// Replaces the `<Head>` tags that used to be rendered by the page component.
export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)

  if (!post) {
    return { title: 'Post Not Found' }
  }

  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params
  const [post, comments] = await Promise.all([getPost(id), getComments(id)])

  if (!post) {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

