'use client' // Error boundaries must be Client Components

// Replaces `pages/_error.js` for errors thrown in the root layout. It renders
// its own document, so it must include <html> and <body>.
export default function GlobalError({
  error,
  retry,
}: {
  error: Error & { digest?: string }
  retry: () => void
}) {
  return (
    <html lang="en">
      <body>
        <title>Error - My Blog</title>
        <div className="error-page">
          <h1>An error occurred on server</h1>
          <p>Sorry, something went wrong.</p>
          {error.digest ? <p>Error ID: {error.digest}</p> : null}
          <button onClick={() => retry()}>Try again</button>
        </div>
      </body>
    </html>
  )
}

