import type { NextRequest } from 'next/server'
import type { ApiPost } from '@/lib/posts'

// Replaces `pages/api/posts/index.js`. Unsupported methods are answered with a
// `405` and an `Allow` header by Next.js automatically.
export async function GET(): Promise<Response> {
  // Simulate fetching posts
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return Response.json(posts)
}

export async function POST(request: NextRequest): Promise<Response> {
  let body: Partial<Pick<ApiPost, 'title' | 'content'>>

  try {
    body = await request.json()
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const { title, content } = body

  if (!title || !content) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  // Simulate creating a post
  const newPost: ApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return Response.json(newPost, { status: 201 })
}

