import type { NextRequest } from 'next/server'
import type { ApiPost } from '@/lib/posts'

// Replaces `pages/api/posts/[id].js`. `params` is a promise in the App Router,
// and unsupported methods get an automatic `405` with an `Allow` header.
type RouteParams = { params: Promise<{ id: string }> }

export async function GET(
  _request: NextRequest,
  { params }: RouteParams
): Promise<Response> {
  const { id } = await params

  // Simulate fetching a single post
  const post: ApiPost = {
    id: parseInt(id),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(
  request: NextRequest,
  { params }: RouteParams
): Promise<Response> {
  const { id } = await params

  let body: Partial<Pick<ApiPost, 'title' | 'content'>>

  try {
    body = await request.json()
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const { title, content } = body

  // Simulate updating a post
  const updatedPost: ApiPost = {
    id: parseInt(id),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: NextRequest,
  { params }: RouteParams
): Promise<Response> {
  const { id } = await params

  // Simulate deleting a post
  return Response.json({ message: `Post ${id} deleted successfully` })
}

